__NUXT_JSONP__("/finanzas-publicas/noticias/guerra_deja_mas_dinero_publico_por_crudo_pero_menos_por_subsidios_a_gasolinas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{post:{slug:"guerra_deja_mas_dinero_publico_por_crudo_pero_menos_por_subsidios_a_gasolinas",title:"Guerra deja más dinero público por crudo, pero menos por subsidios a gasolinas",date:"2026-03-10T19:23:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F22048ca7-6ed7-4d8d-bb4f-eaa3dcece781\u002F","img-alt":"Gasolina",autor:"Dainzú Patiño, Expansión",link:"https:\u002F\u002Fexpansion.mx\u002Feconomia\u002F2026\u002F03\u002F09\u002Fguerra-dinero-publico-crudo-menos-subsidios-gasolinas",category:"finanzas-publicas",extracto:"En 2022, la pérdida recaudatoria por subsidio a la gasolina fue por más de un punto del PIB, algo preocupante en términos de recaudación, explicó Liliana Alvarado, directora general de Ethos.",toc:[{id:e,depth:2,text:f}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"De prolongarse las alzas en los precios del petróleo y del dólar, provocadas por la guerra en Irán, los ingresos que obtiene México por la venta de la mezcla mexicana pueden ser mayores, pero esto no significará una ganancia en el total de las finanzas públicas, pues al subir el precio del petróleo, sube la gasolina, y Hacienda pierde dinero por otorgar subsidios a los combustibles, tras el objetivo de amortizar las alzas en los precios."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para el presupuesto público de este año, la secretaría de Hacienda estimó el precio de la mezcla mexicana de petróleo en 54.9 dólares. El pasado viernes esta cerró en 84 dólares por barril; 29.1 dólares más que lo programado."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De acuerdo con estimaciones de Hacienda, por cada dólar extra que se coloque el precio de la mezcla mexicana por arriba de los 54.9 dólares estimados (promedio anual), el erario recibe 11,600 millones de pesos más a lo previsto."}]},{type:a,value:c},{type:b,tag:"h2",props:{id:e},children:[{type:b,tag:g,props:{ariaHidden:h,href:"#menos-por-subsidios",tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:f}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Pero estos mayores ingresos no significan dinero extra en el total de la cuenta pública, pues cuando suben los precios del crudo, suben los precios de las gasolinas, y el gobierno activa subsidios para amortizar las alzas en los precios de los combustibles, lo que le significa menos dinero por recaudación."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Lo que ganas por precio del petróleo, lo pierdes en estímulo a las gasolinas”, comentó Víctor Gómez Ayala, economista en jefe y analista de Finamex, en la presentación del Balance del primer año del sexenio, Navengando las finanzas públicas de 2025, de México Evalúa."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para este año, las cuotas a la gasolinas Magna y Premium, por el impuesto IEPS, son de 6.70 pesos y 5.65 pesos por litro, y para el diésel de 7.36 pesos, el subsidio radica en aplicar descuentos a estas tasas, lo que significa pérdidas en la recaudación para el erario."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“El precio del petróleo se presupuestó en 54.9 dólares por barril, el día de hoy se amaneció con precios de 119 dólares por barril en el Brent y el WTI, esto significa una pérdida de recursos para el gobierno, porque recordemos que tenemos el subsidio a las gasolinas, y cuando tenemos este tipo de choques externos se activa. Por darles un ejemplo, en 2022, la pérdida recaudatoria por subsidio a la gasolina fue por más de un punto del PIB, algo preocupante en términos de recaudación”, explicó Liliana Alvarado, directora general de Ethos."}]},{type:a,value:c},{type:b,tag:"h4",props:{id:"y-el-tipo-de-cambio"},children:[{type:b,tag:g,props:{ariaHidden:h,href:"#y-el-tipo-de-cambio",tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:"¿Y el tipo de cambio?"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El tipo de cambio también juega en la ecuación. Para el promedio al cierre de año, Hacienda lo estima en 19.3 pesos por dólar. Hoy cerró en 17.76 pesos ."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“El tipo de cambio no solo tiene un impacto sobre el monto del estímulo, sino también sobre los ingresos petroleros. Y aquí es importante que el efecto neto del tipo de cambio más depreciado, va a sonar un poco contra intuitivo, sobre el balance público es positivo, porque los ingresos petroleros que se reciben en pesos tienen un efecto marginal adicional, que compensa el efecto negativo sobre el gasto en el costo financiero”, añadió el especialista de Finamex."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De acuerdo con los Criterios Económicos de Hacienda, el efecto de una apreciación de 20 centavos resulta en un efecto negativo de -4,900 millones de pesos para las arcas públicas."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fguerra_deja_mas_dinero_publico_por_crudo_pero_menos_por_subsidios_a_gasolinas",extension:".md",createdAt:m,updatedAt:m}}],fetch:{},mutations:[]}}("text","element","\n","p","menos-por-subsidios","Menos por subsidios","a","true",-1,"span","icon","icon-link","2026-07-19T00:56:17.244Z")));